import { isString } from 'lodash-es';
import React from 'react';
import type { ReactNode } from 'react-markdown';

import { SecondaryAtom } from '../../../tooltip-atoms/components/SecondaryAtom.js';
import { EmojiShape } from '../../../tooltip-atoms/shapes/EmojiShape.js';
import { IconShape } from '../../../tooltip-atoms/shapes/IconShape.js';
import { TooltipInfoContent } from '../../section-components/TooltipInfoContent.js';
import { TooltipItem } from '../../section-components/TooltipItem.js';
import { TooltipSymbolContent } from '../../section-components/TooltipSymbolContent.js';
import { TooltipValueContent } from '../../section-components/TooltipValueContent.js';

export interface KeyValueProps {
  icon: ReactNode;
  name: string;
  value: string;
  actions?: () => React.ReactElement;
}

export const KeyValue = ({ icon, name, value, actions }: KeyValueProps) => {
  return (
    <TooltipItem actions={actions}>
      <TooltipSymbolContent>
        {isString(icon) ? (
          <EmojiShape>{icon}</EmojiShape>
        ) : (
          <IconShape>{icon}</IconShape>
        )}
      </TooltipSymbolContent>
      <TooltipInfoContent>
        <SecondaryAtom>{name}</SecondaryAtom>
      </TooltipInfoContent>
      <TooltipValueContent>{value}</TooltipValueContent>
    </TooltipItem>
  );
};

KeyValue['displayName'] = 'ChartTooltip.KeyValue';
